    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    groups = []  # Initialize list to store separated groups

    stack = []  # Initialize stack to keep track of open parentheses
    start = 0  # Initialize start index of a group

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                groups.append(paren_string[start:i+1])  # Step 2 & 3: Identify and extract groups of nested parentheses, Separate each group into separate strings

    # Step 4: Ensure each group is balanced (properly closed)
    for group in groups:
        if group.count('(') != group.count(')'):
            raise ValueError("Unbalanced parentheses in group: {}".format(group))

    return groups

